/** Shared wire contract: no secrets, Node APIs, or environment-dependent policy. */
export const VIDEO_PART_BYTES = 8 * 1024 * 1024;
export const VIDEO_UPLOAD_MAX_BYTES = 2_000_000_000;
export const VIDEO_UPLOAD_TYPES = ["video/mp4", "video/webm", "video/quicktime", "video/x-matroska", "video/x-msvideo"] as const;
export const UPLOAD_UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
export const SHA256_BASE64 = /^[A-Za-z0-9+/]{42}[AEIMQUYcgkosw048]=$/;
export function videoPartSize(total: number, partNumber: number) {
  if (!Number.isSafeInteger(total) || total < 1 || total > VIDEO_UPLOAD_MAX_BYTES
      || !Number.isSafeInteger(partNumber) || partNumber < 1 || partNumber > Math.ceil(total / VIDEO_PART_BYTES)) throw new Error("Invalid video upload part");
  return Math.min(VIDEO_PART_BYTES, total - (partNumber - 1) * VIDEO_PART_BYTES);
}
export function validateVideoManifest(total: number, checksums: unknown): asserts checksums is string[] {
  videoPartSize(total, 1);
  if (!Array.isArray(checksums) || checksums.length !== Math.ceil(total / VIDEO_PART_BYTES)
      || checksums.some(value => typeof value !== "string" || !SHA256_BASE64.test(value))) throw new Error("Invalid video checksum manifest");
}
export type MultipartUploadView = {
  id: string; objectKey: string; courseSlug: string; lessonId: string; contentType: string; sizeBytes: number;
  partSize: number; status: string; expiresAt: string; completedParts: number[];
};
